//! Java (native Android, XML layout): TUMR's own minimal template. The Android CLI has only
//! Kotlin / Compose templates, so this one is written for Java, not converted. It has no library
//! dependencies: one `Activity`, one layout, the platform theme.
//!
//! Its Gradle wrapper is the official one generated by Gradle 9.1.0 (`gradle wrapper`), shipped
//! with TUMR; the JAR's SHA-256 is checked before it is written (owner decision CRT-D6) and
//! matches Gradle's published checksum for 9.1.0. The wrapper properties pin the distribution and
//! its checksum.

use std::path::Path;
use std::sync::atomic::AtomicBool;

use sha2::{Digest, Sha256};

use super::{package_path, versions, write};
use crate::job::Creator;
use crate::request::Validated;
use crate::Framework;

/// SHA-256 of `gradle-wrapper.jar` from Gradle 9.1.0
/// (<https://services.gradle.org/distributions/gradle-9.1.0-wrapper.jar.sha256>).
pub const WRAPPER_JAR_SHA256: &str =
    "76805e32c009c0cf0dd5d206bddc9fb22ea42e84db904b764f3047de095493f3";

const WRAPPER_JAR: &[u8] = include_bytes!("../../templates/java/gradle/wrapper/gradle-wrapper.jar");

/// Text files: (path in the project, contents with `{{…}}` placeholders).
const TEXT: &[(&str, &str)] = &[
    (
        ".gitignore",
        include_str!("../../templates/java/.gitignore"),
    ),
    (
        "build.gradle.kts",
        include_str!("../../templates/java/build.gradle.kts"),
    ),
    (
        "settings.gradle.kts",
        include_str!("../../templates/java/settings.gradle.kts"),
    ),
    (
        "gradle.properties",
        include_str!("../../templates/java/gradle.properties"),
    ),
    (
        "gradle/libs.versions.toml",
        include_str!("../../templates/java/gradle/libs.versions.toml"),
    ),
    (
        "gradle/wrapper/gradle-wrapper.properties",
        include_str!("../../templates/java/gradle/wrapper/gradle-wrapper.properties"),
    ),
    ("gradlew", include_str!("../../templates/java/gradlew")),
    (
        "gradlew.bat",
        include_str!("../../templates/java/gradlew.bat"),
    ),
    (
        "app/.gitignore",
        include_str!("../../templates/java/app/.gitignore"),
    ),
    (
        "app/build.gradle.kts",
        include_str!("../../templates/java/app/build.gradle.kts"),
    ),
    (
        "app/src/main/AndroidManifest.xml",
        include_str!("../../templates/java/app/src/main/AndroidManifest.xml"),
    ),
    (
        "app/src/main/res/layout/activity_main.xml",
        include_str!("../../templates/java/app/src/main/res/layout/activity_main.xml"),
    ),
    (
        "app/src/main/res/values/strings.xml",
        include_str!("../../templates/java/app/src/main/res/values/strings.xml"),
    ),
    (
        "app/src/main/res/values/themes.xml",
        include_str!("../../templates/java/app/src/main/res/values/themes.xml"),
    ),
];

const MAIN_ACTIVITY: &str =
    include_str!("../../templates/java/app/src/main/java/MainActivity.java");
const WRAPPER_JAR_PATH: &str = "gradle/wrapper/gradle-wrapper.jar";

pub struct Java;

fn main_activity_path(package_id: &str) -> String {
    format!(
        "app/src/main/java/{}/MainActivity.java",
        package_path(package_id)
    )
}

/// The SHA-256 of `bytes` in lower-case hex.
fn sha256_hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    Sha256::digest(bytes)
        .iter()
        .fold(String::with_capacity(64), |mut s, b| {
            let _ = write!(s, "{b:02x}");
            s
        })
}

fn fill(text: &str, v: &Validated) -> String {
    text.replace("{{NAME}}", &v.name)
        .replace("{{NAME_XML}}", &v.name)
        .replace("{{PACKAGE}}", &v.package_id)
        .replace("{{AGP}}", versions::JAVA_AGP)
        .replace("{{COMPILE_SDK}}", &versions::JAVA_COMPILE_SDK.to_string())
}

impl Creator for Java {
    fn framework(&self) -> Framework {
        Framework::Java
    }

    fn create(
        &self,
        v: &Validated,
        target: &Path,
        out: &mut dyn FnMut(&str),
        _cancel: &AtomicBool,
    ) -> Result<(), String> {
        let sum = sha256_hex(WRAPPER_JAR);
        if sum != WRAPPER_JAR_SHA256 {
            return Err(format!(
                "the Gradle wrapper shipped with TUMR is damaged (SHA-256 {sum}, expected {WRAPPER_JAR_SHA256}); reinstall TUMR"
            ));
        }
        out("Gradle wrapper 9.1.0 checked (SHA-256 matches)");
        for (path, text) in TEXT {
            write(&target.join(path), &fill(text, v))?;
        }
        write(
            &target.join(main_activity_path(&v.package_id)),
            &fill(MAIN_ACTIVITY, v),
        )?;
        let jar = target.join(WRAPPER_JAR_PATH);
        std::fs::write(&jar, WRAPPER_JAR)
            .map_err(|e| format!("cannot write {}: {e}", jar.display()))?;
        out(&format!(
            "wrote the Java template (Android Gradle plugin {}, compileSdk {})",
            versions::JAVA_AGP,
            versions::JAVA_COMPILE_SDK
        ));
        Ok(())
    }

    fn expected_files(&self, v: &Validated) -> Vec<String> {
        let mut files: Vec<String> = TEXT.iter().map(|(p, _)| (*p).to_string()).collect();
        files.push(WRAPPER_JAR_PATH.into());
        files.push(main_activity_path(&v.package_id));
        files
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_shipped_wrapper_is_the_official_one() {
        assert_eq!(sha256_hex(WRAPPER_JAR), WRAPPER_JAR_SHA256);
        let props = TEXT
            .iter()
            .find(|(p, _)| p.ends_with("gradle-wrapper.properties"))
            .unwrap()
            .1;
        assert!(props.contains("gradle-9.1.0-bin.zip"));
        assert!(props.contains("distributionSha256Sum="));
    }

    #[test]
    fn settings_regexes_keep_their_escapes() {
        // Kotlin script strings need `\\.`; a single backslash does not compile
        let settings = TEXT
            .iter()
            .find(|(p, _)| *p == "settings.gradle.kts")
            .unwrap()
            .1;
        assert!(settings.contains(r#"includeGroupByRegex("com\\.android.*")"#));
    }

    #[test]
    fn no_placeholder_is_left() {
        let v = Validated {
            framework: Framework::Java,
            name: "Hello App".into(),
            package_id: "com.example.helloapp".into(),
            target: std::env::temp_dir(),
            creates_folder: true,
            agent: None,
            trust: false,
            warnings: Vec::new(),
        };
        for (p, t) in TEXT {
            assert!(!fill(t, &v).contains("{{"), "{p}");
        }
        let main = fill(MAIN_ACTIVITY, &v);
        assert!(main.starts_with("package com.example.helloapp;"));
        assert_eq!(
            main_activity_path(&v.package_id),
            "app/src/main/java/com/example/helloapp/MainActivity.java"
        );
    }
}
